    public static class CastroAlves
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "Eu sinto em mim o borbulhar do gênio", Author = "Castro Alves" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "Que sou pequeno — mas só fito os Andes.", Author = "Castro Alves" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "O meu cinismo passa a misantropia. Acho-me bastante afetado do peito, tenho sofrido muito. Essa apatia mata-me.", Author = "Castro Alves" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "Trevas e luz. Tormentas e bonanças. Amargos e ambrosias... É assim que eu vivo... A dor e o prazer são as únicas afirmações da existência... Convenço-me então de que existo.", Author = "Castro Alves" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "Em mim a preguiça é proverbial.", Author = "Castro Alves" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "Sou preguiçoso (Isto é velho).", Author = "Castro Alves" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "É um canto do futuro. O canto da esperança e nós não devemos esperar? Sim, e muito e sempre...", Author = "Castro Alves" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "Caminhai, moços, ide ao teatro. Entrai, homens do povo, bebei a luz daquele tabernáculo.", Author = "Castro Alves" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "Sabe que o meu trabalho precisa de uma plateia ilustrada. Precisa talvez mesmo de uma plateia acadêmica. O lirismo, o patriotismo, a linguagem creio que serão bem recebidos por corações de vinte anos, porque o Gonzaga é feito para a mocidade.", Author = "Castro Alves" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "Eis-me aqui na Corte há quatro dias, eu, pobre inválido, que não podia chegar até a sala!... Que força, que mola estranha deu vida ao cadáver? Foi Deus. O Deus de Lázaro sustentou-me nesse instante em que a amizade acompanhou-me.", Author = "Castro Alves" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "Oh! Bendito o que semeia Livros... livros à mão-cheia... E manda o povo pensar! O livro caindo n'alma É gérmen — que faz a palma, É chuva — que faz o mar.", Author = "Castro Alves" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "Trema a terra de susto aterrada... Minha égua veloz, desgrenhada, Negra, escura nas lapas voou. Trema o céu ... ó ruína! ó desgraça! Porque o negro bandido é quem passa, Porque o negro bandido bradou:", Author = "Castro Alves" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "Cai, orvalho de sangue do escravo, Cai, orvalho, na face do algoz. Cresce, cresce, seara vermelha, Cresce, cresce, vingança feroz.", Author = "Castro Alves" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "O poeta é o músico da inteligência, assim como o músico é o poeta do ouvido.", Author = "Castro Alves" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "A poesia assimila a si todas as nuances das ideias das épocas, enroupa-se do manto da natureza, que a cerca.", Author = "Castro Alves" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "A poesia, pois, na terra dos Andradas, dos Pedros Ivos, e dos Tiradentes deve ser majestosa como as matas virgens da América, arrojada, como seus rios gigantes, livre, como os ventos, que passam gementes por suas várzeas, que zurzem os costados pedregosos dos seus gigantes de granito. A poesia enfim deve de ser o reflexo desta terra.", Author = "Castro Alves" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "O poeta é uma harpa entregue às ventanias da noite, onde a brisa acha um canto de amor, o vento frio das desoras um lamento, o vendaval um trono lúgubre de morte.", Author = "Castro Alves" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "A poesia moralizadora e filosófica é o noivado da fantasia com a razão. Poesia sublime, que cantando ensina, maldizendo regenera, chorando purifica.", Author = "Castro Alves" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "A poesia moral, filtrando no coração, aí entorna o perfume da virtude, e mesmo quando a memória tem-na esquecido, o coração guarda dela uma reminiscência suave, como essas ânforas antigas, quando mesmo esgotadas, rescendem os aromas, que se lhe conglutinaram.", Author = "Castro Alves" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "No Brasil, onde há tanto talento, mas também tanto marasmo, os poucos sacerdotes da poesia não devem consentir que o fogo sagrado se extinga no sacrário da inteligência.", Author = "Castro Alves" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "A poesia é um sacerdócio. — Seu Deus — o belo. — Seu turibulário — o Poeta.", Author = "Castro Alves" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "Adeus, irmão desta alma, digo-te Adeus! Mas deixa que eu evite esse jamais! — Que o céu se compadeça aos rogos meus E um dia cessarão teus e meus ais!", Author = "Eugênia Câmara" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "Sim que Deus iluminou a tua fronte Com um raio divinal de Gênio! e Glória!... Vive, sonha, canta, este horizonte!... O Brasil quer teu nome em sua história", Author = "Eugênia Câmara" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "A Família, esse Lar augusto e Santo! Cercará teu sofrer de muito amor. Em regaço de irmãs irá teu pranto Salvar-te junto ao trono do Senhor.", Author = "Eugênia Câmara" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "Falas-me em risos! a mim Das afeições descrente e nua!... Pode-se encontrar outra alma Depois de reinar na tua?!!! Da perdida criatura O corpo da terra é, Mas a alma voa ao céu Levando a crença e a fé. E eu levo na hora extrema A tua pálida imagem Gravada dentro em minh'alma Como celeste miragem!", Author = "Eugênia Câmara" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "O Gérmen de que me falas Crença! e Fé! não é mortal, Deus olha piedoso o Mártir Triunfarás desse mal.", Author = "Eugênia Câmara" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "Eu não me iludo. Eu te amo! Quer na vida quer na morte; A um só dos teus olhares Será tua a minha sorte.", Author = "Eugênia Câmara" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "Aquela noute!... oh! silêncio Noute de fel e de amor Em que dentro em duas almas Houve um poema de dor!...", Author = "Eugênia Câmara" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "A multidão me sorria E o meu ser estava contigo, Nesse olhar belo e sereno Minh'alma encontrou abrigo.", Author = "Eugênia Câmara" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "Eras o anjo d'outra hora E eu cairia a teus pés Se inda mesmo moribundo Tu me dissesses — Talvez!...", Author = "Eugênia Câmara" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "Saí! dali alquebrada Sem forças para lutar Com desejos de morrer, Com vida p'ra te adorar.", Author = "Eugênia Câmara" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "Foi minha filha entre nós O Anjo da redenção Falei-lhe de ti! Chorou!... Foi seu pranto meu — Perdão!...", Author = "Eugênia Câmara" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Castro_Alves", Text = "Adeus! Se um dia o Destino Nos fizer ainda encontrar Como irmã ou como amante Sempre! Sempre! me hás de achar.", Author = "Eugênia Câmara" },
        };
    }
